// Welzl 3D minimum enclosing ball; see package README and bundled MIT notice.
#[derive(Clone,Copy,Default)] struct P{ x:f64,y:f64,z:f64 }
#[derive(Clone,Copy)] struct S{ c:P,r:f64 }
fn sub(a:P,b:P)->P{P{x:a.x-b.x,y:a.y-b.y,z:a.z-b.z}} fn add(a:P,b:P)->P{P{x:a.x+b.x,y:a.y+b.y,z:a.z+b.z}} fn mul(a:P,k:f64)->P{P{x:a.x*k,y:a.y*k,z:a.z*k}} fn dot(a:P,b:P)->f64{a.x*b.x+a.y*b.y+a.z*b.z} fn cross(a:P,b:P)->P{P{x:a.y*b.z-a.z*b.y,y:a.z*b.x-a.x*b.z,z:a.x*b.y-a.y*b.x}} fn det(a:P,b:P,c:P)->f64{dot(a,cross(b,c))} fn invalid()->S{S{c:P::default(),r:-1.0}}
fn through(p:&[P])->S{match p.len(){1=>S{c:p[0],r:0.0},2=>{let c=mul(add(p[0],p[1]),0.5);S{c,r:dot(sub(p[0],c),sub(p[0],c)).sqrt()}},3=>{let u=sub(p[1],p[0]);let v=sub(p[2],p[0]);let w=cross(u,v);let d=2.0*dot(w,w);if d<1e-24{return invalid()}let o=mul(add(mul(cross(v,w),dot(u,u)),mul(cross(w,u),dot(v,v))),1.0/d);let c=add(p[0],o);S{c,r:dot(sub(c,p[0]),sub(c,p[0])).sqrt()}},4=>{let a=mul(sub(p[1],p[0]),2.0);let b=mul(sub(p[2],p[0]),2.0);let c=mul(sub(p[3],p[0]),2.0);let qa=dot(p[1],p[1])-dot(p[0],p[0]);let qb=dot(p[2],p[2])-dot(p[0],p[0]);let qc=dot(p[3],p[3])-dot(p[0],p[0]);let d=det(a,b,c);if d.abs()<1e-18{return invalid()}let center=mul(add(add(mul(cross(b,c),qa),mul(cross(c,a),qb)),mul(cross(a,b),qc)),1.0/d);S{c:center,r:dot(sub(center,p[0]),sub(center,p[0])).sqrt()}},_=>invalid()}}
fn contains(s:S,p:P)->bool{if s.r<0.0{return false}let d=sub(p,s.c);dot(d,d)<=(s.r+1e-10)*(s.r+1e-10)}
fn fit(r:&[P;4],m:usize)->S{let mut best=invalid();for mask in 1..(1usize<<m){let mut q=[P::default();4];let mut n=0;for i in 0..m{if mask&(1<<i)!=0{q[n]=r[i];n+=1}}let s=through(&q[..n]);if s.r<0.0{continue}let mut ok=true;for i in 0..m{if !contains(s,r[i]){ok=false}}if ok&&(best.r<0.0||s.r<best.r-1e-12){best=s}}best}
fn welzl(p:&[P],n:usize,r:&mut [P;4],m:usize)->S{if n==0||m==4{return fit(r,m)}let s=welzl(p,n-1,r,m);if contains(s,p[n-1]){return s}r[m]=p[n-1];welzl(p,n-1,r,m+1)}
#[no_mangle] pub unsafe extern "C" fn smallest_enclosing_ball_3d(input:*const f64,length:usize,output:*mut f64,capacity:usize)->i64{if input.is_null()||length<4||length>25{return -1}let v=std::slice::from_raw_parts(input,length);if !v[0].is_finite()||v[0]<1.0||v[0]>8.0||v[0]!=v[0].floor(){return -1}let n=v[0] as usize;if length!=1+3*n{return -1}let mut p=[P::default();8];for i in 0..n{p[i]=P{x:v[1+3*i],y:v[2+3*i],z:v[3+3*i]};if !p[i].x.is_finite()||!p[i].y.is_finite()||!p[i].z.is_finite()||p[i].x.abs()>10.0||p[i].y.abs()>10.0||p[i].z.abs()>10.0{return -1}}p[..n].sort_by(|a,b|a.x.total_cmp(&b.x).then(a.y.total_cmp(&b.y)).then(a.z.total_cmp(&b.z)));let mut r=[P::default();4];let s=welzl(&p[..n],n,&mut r,0);if s.r<0.0||!s.r.is_finite(){return -1}if output.is_null()||capacity<4{return -2}let o=std::slice::from_raw_parts_mut(output,capacity);o[0]=s.c.x;o[1]=s.c.y;o[2]=s.c.z;o[3]=s.r;4}
